"""Authentication endpoints: register, login, current user."""

from __future__ import annotations

import re

from fastapi import APIRouter, Depends, status
from pydantic import BaseModel, Field
from sqlite3 import Connection

from app.config import Settings, get_settings
from app.db import get_db, utc_now, audit
from app.errors import bad_request, conflict, unauthorized
from app.security import (
    hash_password,
    verify_password,
    create_access_token,
    password_problem,
    get_current_user,
    CurrentUser,
)

router = APIRouter(prefix="/api/auth", tags=["auth"])

USERNAME_PATTERN = re.compile(r"^[A-Za-z0-9_-]{3,32}$")

class RegisterRequest(BaseModel):
    username: str = Field(..., min_length=3, max_length=32)
    password: str = Field(..., min_length=1)

class RegisterResponse(BaseModel):
    id: int
    username: str
    created_at: str

class LoginRequest(BaseModel):
    username: str
    password: str

class LoginResponse(BaseModel):
    access_token: str
    token_type: str = "bearer"
    expires_in: int

class MeResponse(BaseModel):
    id: int
    username: str
    created_at: str

@router.post(
    "/register",
    response_model=RegisterResponse,
    status_code=status.HTTP_201_CREATED,
    summary="Create a new account",
)
def register(
    data: RegisterRequest,
    conn: Connection = Depends(get_db),
    settings: Settings = Depends(get_settings),
) -> RegisterResponse:
    """Register a new user."""
    username = data.username.strip()
    password = data.password

    if not USERNAME_PATTERN.fullmatch(username):
        raise bad_request("invalid_username", "Username must be 3-32 letters, digits, _ or -.")

    problem = password_problem(password)
    if problem:
        raise bad_request("weak_password", problem)

    existing = conn.execute("SELECT id FROM users WHERE username = ?", (username,)).fetchone()
    if existing:
        raise conflict("username_taken", "This username is already taken.")

    now = utc_now()
    password_hash = hash_password(password)
    cursor = conn.execute(
        "INSERT INTO users (username, password_hash, created_at) VALUES (?, ?, ?)",
        (username, password_hash, now),
    )
    user_id = cursor.lastrowid
    audit(conn, "register", user_id, f"username={username}")
    return RegisterResponse(id=user_id, username=username, created_at=now)

@router.post("/login", response_model=LoginResponse, summary="Sign in and get an access token")
def login(
    data: LoginRequest,
    conn: Connection = Depends(get_db),
    settings: Settings = Depends(get_settings),
) -> LoginResponse:
    """Authenticate a user and return an access token."""
    username = data.username.strip()
    password = data.password

    row = conn.execute("SELECT id, password_hash FROM users WHERE username = ?", (username,)).fetchone()

    if row is None or not verify_password(password, row["password_hash"]):
        audit(conn, "login_failed", None, f"username={username}")
        raise unauthorized("invalid_credentials", "Invalid username or password.")

    user_id = row["id"]
    audit(conn, "login", user_id, f"username={username}")
    token = create_access_token(user_id, username, settings)
    return LoginResponse(access_token=token, expires_in=settings.token_ttl)

@router.get("/me", response_model=MeResponse, summary="Current user")
def me(user: CurrentUser = Depends(get_current_user), conn: Connection = Depends(get_db)) -> MeResponse:
    """Return the signed-in user."""
    row = conn.execute("SELECT id, username, created_at FROM users WHERE id = ?", (user.id,)).fetchone()
    if row is None:
        raise unauthorized("invalid_token", "Your session is invalid or has expired.")
    return MeResponse(id=row["id"], username=row["username"], created_at=row["created_at"])
