from __future__ import annotations

from fastapi import APIRouter, Depends, Query, status
from pydantic import BaseModel, Field
from sqlite3 import Connection
from typing import Sequence

from app.config import Settings, get_settings
from app.db import get_db, utc_now
from app.errors import not_found
from app.pagination import PageParams, page_params, paginate
from app.security import get_current_user, CurrentUser

router = APIRouter(prefix="/api/todos", tags=["todos"])

class TodoCreate(BaseModel):
    title: str = Field(..., min_length=1, max_length=200)

class TodoUpdate(BaseModel):
    title: str | None = Field(default=None, min_length=1, max_length=200)
    done: bool | None = None

class TodoResponse(BaseModel):
    id: int
    title: str
    done: bool
    created_at: str
    updated_at: str

def _todo_row_to_response(row: Connection) -> TodoResponse:
    return TodoResponse(
        id=row["id"],
        title=row["title"],
        done=bool(row["done"]),
        created_at=row["created_at"],
        updated_at=row["updated_at"],
    )

@router.get("", response_model=dict, summary="List todos")
def list_todos(
    done: bool | None = Query(default=None, description="Filter by done status"),
    page: PageParams = Depends(page_params),
    user: CurrentUser = Depends(get_current_user),
    conn: Connection = Depends(get_db),
) -> dict:
    """Return the user's todos, newest first, with optional filter and pagination."""
    where = ["user_id = ?"]
    params: list = [user.id]
    if done is not None:
        where.append("done = ?")
        params.append(1 if done else 0)

    where_sql = " AND ".join(where)
    total = conn.execute(f"SELECT COUNT(*) FROM todos WHERE {where_sql}", params).fetchone()[0]

    rows = conn.execute(
        f"SELECT id, title, done, created_at, updated_at FROM todos WHERE {where_sql} "
        f"ORDER BY created_at DESC LIMIT ? OFFSET ?",
        (*params, page.limit, page.offset),
    ).fetchall()

    items = [_todo_row_to_response(row) for row in rows]
    return paginate(items, total, page)

@router.post("", response_model=TodoResponse, status_code=status.HTTP_201_CREATED, summary="Create a todo")
def create_todo(
    data: TodoCreate,
    user: CurrentUser = Depends(get_current_user),
    conn: Connection = Depends(get_db),
) -> TodoResponse:
    """Create a new todo for the signed-in user."""
    title = data.title.strip()
    now = utc_now()
    cursor = conn.execute(
        "INSERT INTO todos (user_id, title, done, created_at, updated_at) VALUES (?, ?, 0, ?, ?)",
        (user.id, title, now, now),
    )
    todo_id = cursor.lastrowid
    row = conn.execute(
        "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ?",
        (todo_id,),
    ).fetchone()
    return _todo_row_to_response(row)

@router.get("/{todo_id}", response_model=TodoResponse, summary="Get a todo")
def get_todo(
    todo_id: int,
    user: CurrentUser = Depends(get_current_user),
    conn: Connection = Depends(get_db),
) -> TodoResponse:
    """Return a single todo belonging to the user."""
    row = conn.execute(
        "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ? AND user_id = ?",
        (todo_id, user.id),
    ).fetchone()
    if row is None:
        raise not_found("todo_not_found", "Todo not found.")
    return _todo_row_to_response(row)

@router.patch("/{todo_id}", response_model=TodoResponse, summary="Update a todo")
def update_todo(
    todo_id: int,
    data: TodoUpdate,
    user: CurrentUser = Depends(get_current_user),
    conn: Connection = Depends(get_db),
) -> TodoResponse:
    """Update title and/or done status of a todo."""
    row = conn.execute(
        "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ? AND user_id = ?",
        (todo_id, user.id),
    ).fetchone()
    if row is None:
        raise not_found("todo_not_found", "Todo not found.")

    updates = []
    params = []
    if data.title is not None:
        updates.append("title = ?")
        params.append(data.title.strip())
    if data.done is not None:
        updates.append("done = ?")
        params.append(1 if data.done else 0)

    if not updates:
        return _todo_row_to_response(row)

    updates.append("updated_at = ?")
    params.append(utc_now())
    params.append(todo_id)

    conn.execute(f"UPDATE todos SET {', '.join(updates)} WHERE id = ?", params)

    row = conn.execute(
        "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ?",
        (todo_id,),
    ).fetchone()
    return _todo_row_to_response(row)

@router.delete("/{todo_id}", status_code=status.HTTP_204_NO_CONTENT, summary="Delete a todo")
def delete_todo(
    todo_id: int,
    user: CurrentUser = Depends(get_current_user),
    conn: Connection = Depends(get_db),
) -> None:
    """Delete a todo belonging to the user."""
    cursor = conn.execute(
        "DELETE FROM todos WHERE id = ? AND user_id = ?",
        (todo_id, user.id),
    )
    if cursor.rowcount == 0:
        raise not_found("todo_not_found", "Todo not found.")
