    renameBtn.addEventListener("click", () => renameTodo(todo.id, titleSpan));
    const deleteBtn = el("button", { type: "button", class: "secondary danger", "aria-label": "Delete" }, "🗑");
    deleteBtn.addEventListener("click", () => deleteTodo(todo.id));
    li.append(checkbox, titleSpan, renameBtn, deleteBtn);
    todoList.append(li);
  }
}

function updatePager(data) {
  const hasPrev = currentOffset > 0;
  const hasNext = currentOffset + data.items.length < data.total;
  prevBtn.disabled = !hasPrev;
  nextBtn.disabled = !hasNext;
  const pageNum = Math.floor(currentOffset / PAGE_SIZE) + 1;
  const totalPages = Math.ceil(data.total / PAGE_SIZE) || 1;
  pageInfo.textContent = `Page ${pageNum} of ${totalPages} (${data.total} total)`;
  pager.hidden = data.total === 0;
}

async function addTodo(title) {
  try {
    await apiFetch("/api/todos", { method: "POST", body: { title } });
    showMessage("Todo added.", "success");
    currentOffset = 0;
    await loadTodos();
  } catch (err) {
    if (err instanceof ApiError) showMessage(err.message, "error");
    else showMessage("Failed to add todo.", "error");
  }
}

async function toggleDone(id, done) {
  try {
    await apiFetch(`/api/todos/${id}`, { method: "PATCH", body: { done } });
    await loadTodos();
  } catch (err) {
    if (err instanceof ApiError) showMessage(err.message, "error");
    else showMessage("Failed to update todo.", "error");
    await loadTodos(); // revert UI
  }
}

async function renameTodo(id, titleSpan) {
  const currentTitle = titleSpan.textContent;
  const input = el("input", { type: "text", value: currentTitle, maxlength: 200 });
  const save = async () => {
    const newTitle = input.value.trim();
    if (newTitle && newTitle !== currentTitle) {
      try {
        await apiFetch(`/api/todos/${id}`, { method: "PATCH", body: { title: newTitle } });
        showMessage("Todo renamed.", "success");
      } catch (err) {
        if (err instanceof ApiError) showMessage(err.message, "error");
        else showMessage("Failed to rename todo.", "error");
      }
    }
    await loadTodos();
  };
  const cancel = () => { await loadTodos(); };
  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter") save();
    else if (e.key === "Escape") cancel();
  });
  input.addEventListener("blur", save);
  clear(titleSpan);
  titleSpan.append(input);
  input.focus();
  input.select();
}

async function deleteTodo(id) {
  if (!confirm("Delete this todo?")) return;
  try {
    await apiFetch(`/api/todos/${id}`, { method: "DELETE" });
    showMessage("Todo deleted.", "success");
    await loadTodos();
  } catch (err) {
    if (err instanceof ApiError) showMessage(err.message, "error");
    else showMessage("Failed to delete todo.", "error");
  }
}

function setFilter(filter) {
  currentFilter = filter;
  currentOffset = 0;
  if (filter === null) setActiveFilter(filterAllBtn);
  else if (filter === false) setActiveFilter(filterOpenBtn);
  else setActiveFilter(filterDoneBtn);
